// Builds the plain-language place name for every census tract.
//
//   node scripts/build_place_names.mjs       (or: npm run build:places)
//
// Input:  data/audit_output/tract_npa_overlap.json — for each tract, the
//         share of its area inside each City of Austin Neighborhood Planning
//         Area (NPA), produced by scripts/assign_names_by_area.cjs.
// Output: data/placeNames.js (generated — re-run this script, do not edit).
//
// A tract only gets a neighborhood name when a City planning-area polygon
// supports it. The rule, in order:
//
//   named     one planning area covers 80% or more of the tract  -> "Montopolis"
//   split     two planning areas each cover 25% or more          -> "Govalle / Holly area"
//   majority  one planning area covers 50% or more               -> "Old West Austin area"
//   (none)    otherwise the tract keeps its census number        -> "Census tract 419"
//
// Tracts with no entry in the output fall in the last group: mostly suburban
// tracts outside planning-area coverage. Earlier heuristic names for those
// (radius and name-cluster guesses) were removed on purpose in August 2026
// and are not used here.

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const SRC = join(ROOT, "data", "audit_output", "tract_npa_overlap.json");
const OUT = join(ROOT, "data", "placeNames.js");

const NAMED_MIN = 80;
const MAJORITY_MIN = 50;
const SPLIT_MIN = 25;

// The City file lower-cases the second half of hyphenated names.
const tidy = (name) => name.replace(/-([a-z])/g, (_, c) => `-${c.toUpperCase()}`);

const rows = JSON.parse(readFileSync(SRC, "utf8"));
const out = {};
const tally = { named: 0, split: 0, majority: 0, none: 0 };

for (const row of rows) {
  const overlaps = (row.npa_overlaps || [])
    .filter((o) => o.pct > 0)
    .sort((a, b) => b.pct - a.pct);
  const [first, second] = overlaps;
  let entry = null;

  if (first && first.pct >= NAMED_MIN) {
    entry = { title: tidy(first.npa), basis: "named", areas: [[tidy(first.npa), Math.round(first.pct)]] };
  } else if (first && second && first.pct >= SPLIT_MIN && second.pct >= SPLIT_MIN) {
    entry = {
      title: `${tidy(first.npa)} / ${tidy(second.npa)} area`,
      basis: "split",
      areas: [[tidy(first.npa), Math.round(first.pct)], [tidy(second.npa), Math.round(second.pct)]],
    };
  } else if (first && first.pct >= MAJORITY_MIN) {
    entry = { title: `${tidy(first.npa)} area`, basis: "majority", areas: [[tidy(first.npa), Math.round(first.pct)]] };
  }

  if (entry) {
    out[row.region_id] = entry;
    tally[entry.basis]++;
  } else {
    tally.none++;
  }
}

const lines = Object.keys(out)
  .map(Number)
  .sort((a, b) => a - b)
  .map((id) => `  ${id}: ${JSON.stringify(out[id])},`);

const file = [
  "// Auto-generated by scripts/build_place_names.mjs — do not edit by hand.",
  "// Plain-language place names for census tracts, each backed by the share of",
  "// the tract inside a City of Austin Neighborhood Planning Area. Tracts not",
  "// listed here are shown by census tract number. See the script for the rule.",
  "export const PLACE_NAMES = {",
  ...lines,
  "};",
  "",
].join("\n");

writeFileSync(OUT, file);
console.log(`data/placeNames.js: ${rows.length} tracts ->`, tally);
